CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL, email varchar(180) NOT NULL UNIQUE, password varchar(100) NOT NULL, role varchar(20) NOT NULL, status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE families (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_name varchar(160) NOT NULL, phone varchar(30) NOT NULL, address varchar(250) NOT NULL, municipality varchar(80) NOT NULL, status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE children (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES families(id), name varchar(160) NOT NULL, birth_date date NOT NULL, school varchar(180), grade varchar(80), status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(180) NOT NULL, description varchar(1000), goal numeric(14,2) NOT NULL, start_date date NOT NULL, end_date date NOT NULL, status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE donors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES users(id), name varchar(180) NOT NULL, type varchar(20) NOT NULL, email varchar(180) NOT NULL, phone varchar(30), status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE donations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), donor_id uuid NOT NULL REFERENCES donors(id), campaign_id uuid REFERENCES campaigns(id), type varchar(20) NOT NULL, amount numeric(14,2), description varchar(500), quantity integer, material_type varchar(30), status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE needs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES families(id), child_id uuid REFERENCES children(id), type varchar(30) NOT NULL, priority varchar(20) NOT NULL, status varchar(20) NOT NULL, description varchar(500) NOT NULL, requested_quantity integer NOT NULL CHECK(requested_quantity > 0), fulfilled_quantity integer NOT NULL DEFAULT 0 CHECK(fulfilled_quantity >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) NOT NULL UNIQUE, type varchar(30) NOT NULL, description varchar(500) NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), available_quantity integer NOT NULL CHECK(available_quantity >= 0), status varchar(20) NOT NULL, donation_id uuid NOT NULL REFERENCES donations(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), need_id uuid NOT NULL REFERENCES needs(id), resource_id uuid NOT NULL REFERENCES resources(id), quantity integer NOT NULL CHECK(quantity > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE TABLE deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES assignments(id), volunteer_id uuid NOT NULL REFERENCES users(id), delivery_date timestamptz NOT NULL, observations varchar(1000), status varchar(20) NOT NULL, evidence_path varchar(500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
CREATE INDEX idx_users_email ON users(email); CREATE INDEX idx_families_municipality ON families(municipality); CREATE INDEX idx_families_status ON families(status); CREATE INDEX idx_children_family ON children(family_id); CREATE INDEX idx_needs_family ON needs(family_id); CREATE INDEX idx_needs_status ON needs(status); CREATE INDEX idx_needs_priority ON needs(priority); CREATE INDEX idx_needs_type ON needs(type); CREATE INDEX idx_donations_donor ON donations(donor_id); CREATE INDEX idx_donations_campaign ON donations(campaign_id); CREATE INDEX idx_resources_status ON resources(status); CREATE INDEX idx_resources_donation ON resources(donation_id); CREATE INDEX idx_assignments_need ON assignments(need_id); CREATE INDEX idx_assignments_resource ON assignments(resource_id); CREATE INDEX idx_deliveries_assignment ON deliveries(assignment_id); CREATE INDEX idx_deliveries_volunteer ON deliveries(volunteer_id); CREATE INDEX idx_deliveries_status ON deliveries(status);
